package local.pocketchat;
import android.content.*;import android.os.*;import android.widget.*;import org.json.*;import java.io.*;
public class DownloadCenterTestActivity extends DownloadCenterActivity {
  @Override public void onCreate(Bundle b){try{DefaultDownloads.Target target=DefaultDownloads.local(this,"round2-native-download.txt");try(java.io.OutputStream out=target.output()){out.write("native-download-fixture".getBytes(java.nio.charset.StandardCharsets.UTF_8));}target.publish();DownloadLibrary.get(this).add(this,J.obj("id","round2-native-saved","uri",target.uri.toString(),"name",target.name,"mime","text/plain","state","saved","location",target.location));}catch(Exception e){throw new IllegalStateException("Native download fixture failed",e);}for(int i=0;i<6;i++)try{DefaultDownloads.Target item=DefaultDownloads.local(this,"scroll-fixture-"+i+".txt");try(java.io.OutputStream out=item.output()){out.write(i);}item.publish();DownloadLibrary.get(this).add(this,J.obj("id","scroll-fixture-"+i,"uri",item.uri.toString(),"name",item.name,"mime","text/plain","state","saved","location",item.location));}catch(Exception e){throw new IllegalStateException(e);}super.onCreate(b);new Handler(Looper.getMainLooper()).postDelayed(()->{JSONArray checks=new JSONArray(),rows=DownloadLibrary.get(this).list();checks.put(J.obj("name","Opening native download center does not create chat or network","pass",ChatSession.peek()==null));checks.put(J.obj("name","Saved files remain indexed after process recreation","pass",rows.length()>0&&box.getChildCount()>3));android.app.AlertDialog folder=DesignDownloads.folder(this);boolean label=WindowHomeTestActivity.text(folder.getWindow().getDecorView()).contains("默认位置");folder.dismiss();checks.put(J.obj("name","Download location details remain accessible without a persistent instruction block","pass",label));checks.put(J.obj("name","Native saved file actions are available","pass",actions!=null));try{boolean readable=false;for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(row.optString("id").equals("round2-native-saved"))try(java.io.InputStream in=getContentResolver().openInputStream(android.net.Uri.parse(row.optString("uri")))){readable=J.text(in,1024).equals("native-download-fixture");}}checks.put(J.obj("name","Saved fixture opens through the actual read-only provider","pass",readable));stableChecks(checks);filter=3;refresh();
checks.put(J.obj("name","Failed filter has a specific empty state and recovery action","pass",WindowHomeTestActivity.text(box).contains("没有失败的下载")&&WindowHomeTestActivity.text(box).contains("查看全部下载")));
Bundle saved=new Bundle();onSaveInstanceState(saved);checks.put(J.obj("name","Download filter is retained for activity recreation","pass",saved.getInt("filter")==3));
filter=0;refresh();handler.postDelayed(()->{android.widget.ScrollView scroll=(android.widget.ScrollView)box.getParent();scroll.scrollTo(0,300);int y=scroll.getScrollY();refresh();handler.postDelayed(()->{checks.put(J.obj("name","Live download refresh preserves the current scroll position","pass",y>0&&scroll.getScrollY()==y));try{J.write(new File(getFilesDir(),"download-center-results.json"),J.obj("checks",checks).toString(2));}catch(Exception ignored){}},200);},200);}catch(Exception ignored){}},200);}
  void stableChecks(JSONArray checks){
    long now=System.currentTimeMillis();JSONObject saved=J.obj("id","stable-file","slot",0,"name","saved.txt","uri","content://fixture/saved","state","saved","time",1609459200000L,"location","fixture");
    JSONObject active=J.obj("id","stable-progress","slot",7,"name","active.bin","state","downloading","time",1000,"received",10,"total",100,"updated",now);
    JSONArray data=DesignDownloads.ordered(new JSONArray().put(saved),new JSONArray().put(active));android.view.View screen=root,scroll=box.getParent() instanceof android.view.View?(android.view.View)box.getParent():null;
    downloadsView.apply(data,0,now);DesignDownloads.Row row=downloadsView.views.get(DesignDownloads.key(active));android.view.View card=row.card;card.setFocusableInTouchMode(true);boolean focused=card.requestFocus();
    checks.put(J.obj("name","Active downloads are displayed before newer completed files","pass",downloadsView.list.getChildAt(0)==card));
    checks.put(J.obj("name","Saved file shows its recorded date without using refresh time","pass",downloadsView.views.get(DesignDownloads.key(saved)).time.getText().toString().equals(DesignDownloads.timeLabel(saved))&&DesignDownloads.timeLabel(saved).startsWith("保存于 ")));
    JSONObject progress=J.parse(active.toString());DownloadTasks.put(progress,"received",70,"updated",now+1000);JSONArray next=DesignDownloads.ordered(new JSONArray().put(saved),new JSONArray().put(progress));downloadsView.apply(next,0,now+1000);
    checks.put(J.obj("name","Byte progress updates retain screen scroll view card and focused row","pass",root==screen&&box.getParent()==scroll&&downloadsView.views.get(DesignDownloads.key(progress)).card==card&&focused&&card.hasFocus()));
    checks.put(J.obj("name","Existing progress bar updates in place to actual received bytes","pass",row.progress.getProgress()==70&&row.value.optLong("received")==70));
    downloadsView.apply(next,0,now+1000);checks.put(J.obj("name","Identical progress poll does not duplicate or replace rows","pass",downloadsView.list.getChildCount()==2&&downloadsView.list.getChildAt(0)==card));
    JSONObject legacy=J.obj("slot",0,"uri","content://fixture/legacy","state","saved");checks.put(J.obj("name","Legacy unknown date is explicitly shown without inventing a download time","pass",DesignDownloads.timeLabel(legacy).equals("时间未记录")&&DesignDownloads.timeLabel(legacy).equals(DesignDownloads.timeLabel(J.parse(legacy.toString())))));
    refresh();
  }
}
